using System.Text.Json;
using Npgsql;
using NpgsqlTypes;
using OpenSecurityPlatform.Foundation;
namespace OpenSecurityPlatform.Infrastructure;
public sealed class PostgresPersistencePolicyRepository(string connectionString) : IPersistencePolicyRepository, IAsyncDisposable
{
    static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web); readonly NpgsqlDataSource _data = NpgsqlDataSource.Create(connectionString);
    public async Task<IReadOnlyList<PersistencePolicyVersion>> ListAsync(string tenant, CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand("SELECT id,name,version,policy,sha256,status,created_at,created_by FROM platform.persistence_policy_versions WHERE tenant_id=$1 ORDER BY name,version DESC", c); q.Parameters.AddWithValue(Guid.Parse(tenant)); var list = new List<PersistencePolicyVersion>(); await using var r = await q.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(new(r.GetGuid(0), tenant, r.GetString(1), r.GetInt32(2), JsonSerializer.Deserialize<PersistenceTelemetryPolicy>(r.GetString(3), Json)!, r.GetString(4), r.GetString(5), r.GetFieldValue<DateTimeOffset>(6), r.GetString(7))); return list; }
    public async Task<PersistencePolicyVersion> CreateAsync(string tenant, string actor, string name, PersistenceTelemetryPolicy policy, CancellationToken ct) { var errors = PersistenceSafety.Validate(policy); if (errors.Count > 0) throw new EnrollmentConflictException("PERSISTENCE_POLICY_INVALID", string.Join(' ', errors.SelectMany(x => x.Value))); var all = await ListAsync(tenant, ct); var value = new PersistencePolicyVersion(Guid.NewGuid(), tenant, name, all.Where(x => x.Name == name).Select(x => x.Version).DefaultIfEmpty().Max() + 1, policy, PersistenceSafety.EvidenceHash(policy), "active", DateTimeOffset.UtcNow, actor); await using var c = await _data.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand("INSERT INTO platform.persistence_policy_versions VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)", c); object[] values = [value.Id, Guid.Parse(tenant), name, value.Version, JsonSerializer.Serialize(policy, Json), value.Sha256, value.Status, value.CreatedAt, actor]; for (var i = 0; i < values.Length; i++) if (i == 4) q.Parameters.Add(new() { Value = values[i], NpgsqlDbType = NpgsqlDbType.Jsonb }); else q.Parameters.AddWithValue(values[i]); await q.ExecuteNonQueryAsync(ct); return value; }
    public async Task AssignAsync(string tenant, Guid policyId, Guid? endpoint, string actor, CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand("INSERT INTO platform.persistence_policy_assignments VALUES($1,$2,$3,now(),$4) ON CONFLICT(tenant_id,COALESCE(endpoint_id,'00000000-0000-0000-0000-000000000000'::uuid)) DO UPDATE SET policy_id=EXCLUDED.policy_id,assigned_at=now(),assigned_by=EXCLUDED.assigned_by", c); q.Parameters.AddWithValue(Guid.Parse(tenant)); q.Parameters.AddWithValue(endpoint ?? (object)DBNull.Value); q.Parameters.AddWithValue(policyId); q.Parameters.AddWithValue(actor); try { await q.ExecuteNonQueryAsync(ct); } catch (PostgresException) { throw new EnrollmentConflictException("PERSISTENCE_POLICY_ASSIGNMENT_INVALID", "Policy assignment is invalid for this tenant."); } }
    public async Task<EffectivePersistencePolicy> EffectiveAsync(string tenant, Guid endpoint, CancellationToken ct) { var all = await ListAsync(tenant, ct); await using var c = await _data.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand("SELECT policy_id FROM platform.persistence_policy_assignments WHERE tenant_id=$1 AND (endpoint_id=$2 OR endpoint_id IS NULL) ORDER BY endpoint_id NULLS LAST LIMIT 1", c); q.Parameters.AddWithValue(Guid.Parse(tenant)); q.Parameters.AddWithValue(endpoint); var id = await q.ExecuteScalarAsync(ct); var value = id is Guid g ? all.First(x => x.Id == g) : new PersistencePolicyVersion(Guid.Empty, tenant, "safe-default", 0, new(), PersistenceSafety.EvidenceHash(new PersistenceTelemetryPolicy()), "default", DateTimeOffset.UnixEpoch, "system"); await using var acknowledgement = new NpgsqlCommand("SELECT version,applied,validation_error,acknowledged_at FROM platform.persistence_policy_acknowledgements WHERE tenant_id=$1 AND endpoint_id=$2", c); acknowledgement.Parameters.AddWithValue(Guid.Parse(tenant)); acknowledgement.Parameters.AddWithValue(endpoint); await using var reader = await acknowledgement.ExecuteReaderAsync(ct); if (!await reader.ReadAsync(ct)) return new(value, id is null ? "default" : "assigned", endpoint, null, null, null, null, true); var version = reader.GetInt32(0); var applied = reader.GetBoolean(1); return new(value, id is null ? "default" : "assigned", endpoint, reader.GetFieldValue<DateTimeOffset>(3), applied ? version : null, applied ? null : version, reader.IsDBNull(2) ? null : reader.GetString(2), !applied || version != value.Version); }
    public async Task AcknowledgeAsync(string tenant, Guid endpoint, PersistencePolicyAcknowledgement acknowledgement, CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand("INSERT INTO platform.persistence_policy_acknowledgements VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(tenant_id,endpoint_id) DO UPDATE SET policy_id=EXCLUDED.policy_id,version=EXCLUDED.version,applied=EXCLUDED.applied,validation_error=EXCLUDED.validation_error,acknowledged_at=EXCLUDED.acknowledged_at", c); object?[] values = [Guid.Parse(tenant), endpoint, acknowledgement.PolicyId, acknowledgement.Version, acknowledgement.Applied, acknowledgement.ValidationError, acknowledgement.AcknowledgedAt]; foreach (var value in values) q.Parameters.AddWithValue(value ?? DBNull.Value); await q.ExecuteNonQueryAsync(ct); }
    public ValueTask DisposeAsync() => _data.DisposeAsync();
}
